(47, 'caldo de pollo con arroz', 45, 'MEDIA', 74, '[''1 EN UNA CAzUELA SE PONE EL POLLO A COSER, SE LE AGRGA UN CUBITO DE POLLO, POQUITA SAL.'', ''2 EN OTRO SARTEN SE DORA EL ARROZ.'', ''3 YA QUE ESTE DORADO SE LE AGREGA EL CALDO DEL POLLO QUE COCISTE.'', ''4 SE LE PONE UN CUBITO DE TOMATE, CEBOLLA.'', ''5 Y LO PONES A QUE SE CUEZA EL ARROZ.'', ''6 LUEGO QUE YA ESTE COCIDO SELE AGREGA EL POLLO COCIDO. Y YA ESTÁ LISTO PARA COMERSE ESTE RICO POLLO CON ARROZ.'']', 1),
