ON CONFLICT DO NOTHING;

-- Keep PostgreSQL identity sequences ahead of all explicit seed IDs.
SELECT setval(pg_get_serial_sequence('ingredients', 'id'),
              COALESCE((SELECT MAX(id) FROM ingredients), 1), true);
SELECT setval(pg_get_serial_sequence('dishes', 'id'),
              COALESCE((SELECT MAX(id) FROM dishes), 1), true);
SELECT setval(pg_get_serial_sequence('dish_ingredients', 'id'),
              COALESCE((SELECT MAX(id) FROM dish_ingredients), 1), true);
